	if (Object.keys(value).some((key) => !allowed.includes(key))) refuse();
}
export function parseApprovedModels(value: unknown): readonly string[] {
	if (
		!Array.isArray(value) ||
		value.length === 0 ||
		value.length > 256 ||
		!value.every(
			(model) =>
				typeof model === "string" &&
				model.length <= 512 &&
				/^[^\s/]+\/[^\s]+$/.test(model),
